import { Collapsible } from '@base-ui/react/collapsible';
import { ChevronDown } from 'lucide-react';
import { useId, type HTMLAttributes, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { NavContext, navItemKey, useNavListContext, type NavGroup, type NavItem } from './nav-context';
import { navListVariants } from './nav-list.variants';

export type { NavItem, NavGroup, NavIcon } from './nav-context';
import { useI18n } from '../../i18n/I18nProvider';
import { NavListEntry } from './NavListItem';

export interface NavListProps extends Omit<HTMLAttributes<HTMLElement>, 'className'> {
  className?: string;
  ref?: Ref<HTMLElement>;
  groups: NavGroup[];
  /** The current location; the item with this `href` gets aria-current="page". */
  currentHref?: string;
  /** Icon rail: labels hide and become tooltips, group headings become dividers. */
  collapsed?: boolean;
  /** Accessible name of the <nav> landmark. */
  label?: string;
  /** Called after any item is activated (e.g. to close a mobile drawer). */
  onNavigate?: (item: NavItem) => void;
}

function NavGroupSection({ group }: { group: NavGroup }) {
  const { collapsed } = useNavListContext();
  const labelId = useId();
  const s = navListVariants();
  const list = (
    <ul className={s.list()} aria-labelledby={group.label && !collapsed ? labelId : undefined} aria-label={group.label && collapsed ? group.label : undefined}>
      {group.items.map((item) => (
        <NavListEntry key={navItemKey(item)} item={item} />
      ))}
    </ul>
  );

  if (collapsed) {
    return (
      <div className={s.group()}>
        {group.label && <div aria-hidden className={s.railDivider()} />}
        {list}
      </div>
    );
  }

  if (group.collapsible && group.label) {
    return (
      <Collapsible.Root defaultOpen={group.defaultOpen ?? true} className={s.group()}>
        <Collapsible.Trigger className={s.groupTrigger()}>
          <span id={labelId} className={s.groupTriggerLabel()}>
            {group.label}
          </span>
          <ChevronDown size={12} aria-hidden className={s.groupChevron()} />
        </Collapsible.Trigger>
        <Collapsible.Panel className={s.panel()}>{list}</Collapsible.Panel>
      </Collapsible.Root>
    );
  }

  return (
    <div className={s.group()}>
      {group.label && (
        <div id={labelId} className={s.groupLabel()}>
          {group.label}
        </div>
      )}
      {list}
    </div>
  );
}

/**
 * Sidebar navigation: labelled groups (optionally foldable) of items with icon, label, badge and
 * nested collapsible sub-items. The current page gets aria-current="page". `collapsed` turns it
 * into an icon rail with tooltips. Links render through LinkProvider, so client routers work.
 */
export function NavList({ groups, currentHref, collapsed = false, label: labelProp, onNavigate, className, ...props }: NavListProps) {
  const { t } = useI18n();
  const label = labelProp ?? t('common.main');
  const s = navListVariants();
  return (
    <NavContext.Provider value={{ collapsed, currentHref, onNavigate }}>
      <nav aria-label={label} data-collapsed={collapsed || undefined} className={cn(s.root(), className)} {...props}>
        {groups.map((group, i) => (
          <NavGroupSection key={group.id ?? group.label ?? i} group={group} />
        ))}
      </nav>
    </NavContext.Provider>
  );
}

import { Collapsible } from '@base-ui/react/collapsible';
import { Menu as BaseMenu } from '@base-ui/react/menu';
import { ChevronDown } from 'lucide-react';
import { createElement, type MouseEvent, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { useLinkComponent } from '../link';
import { Menu, MenuContent, MenuGroup, MenuGroupLabel, MenuItem, MenuTrigger, menuVariants } from '../menu';
import { SimpleTooltip } from '../tooltip';
import { isNavItemCurrent, navItemContainsCurrent, navItemKey, useNavListContext, type NavItem } from './nav-context';
import { navListVariants } from './nav-list.variants';

const ICON_SIZE = { 0: 17, 1: 15 } as const;

/** Accessible name in the rail, where the visible label and badge are hidden. */
function railLabel(item: NavItem) {
  return typeof item.badge === 'string' || typeof item.badge === 'number' ? `${item.label} (${item.badge})` : item.label;
}

function Badge({ item, current }: { item: NavItem; current: boolean }) {
  const { collapsed } = useNavListContext();
  if (item.badge === undefined || item.badge === null || item.badge === false) return null;
  const s = navListVariants({ current });
  if (collapsed) return <span aria-hidden className={s.railBadge()} />;
  // The space keeps the label and count apart in the accessible name ("Projects 12").
  return (
    <>
      {' '}
      <span className={s.badge()}>{item.badge}</span>
    </>
  );
}

function NavLeaf({ item, depth }: { item: NavItem; depth: number }) {
  const RouterLink = useLinkComponent();
  const { collapsed, currentHref, onNavigate } = useNavListContext();
  const current = isNavItemCurrent(item, currentHref);
  const rail = collapsed && depth === 0;
  const s = navListVariants({ collapsed: rail, current });
  const IconCmp = item.icon;
  const content: ReactNode = (
    <>
      {current && depth === 0 && <span aria-hidden className={s.indicator()} />}
      {IconCmp && <IconCmp size={ICON_SIZE[depth === 0 ? 0 : 1]} aria-hidden className={s.icon()} />}
      {!rail && <span className={s.label()}>{item.label}</span>}
      <Badge item={item} current={current} />
    </>
  );
  const props = {
    className: depth === 0 ? s.item() : s.subItem(),
    'aria-current': current ? ('page' as const) : undefined,
    'aria-label': rail ? railLabel(item) : undefined,
    onClick: (event: MouseEvent<HTMLElement>) => {
      if (item.disabled) {
        event.preventDefault();
        return;
      }
      item.onClick?.(event);
      onNavigate?.(item);
    },
  };
  let element;
  if (item.href !== undefined) {
    const linkProps = { ...props, href: item.href, 'aria-disabled': item.disabled || undefined, tabIndex: item.disabled ? -1 : undefined };
    element = createElement(RouterLink ?? 'a', linkProps, content);
  } else {
    element = (
      <button type="button" disabled={item.disabled} {...props}>
        {content}
      </button>
    );
  }
  return rail ? (
    <SimpleTooltip content={item.label} side="inline-end" arrow={false}>
      {element}
    </SimpleTooltip>
  ) : (
    element
  );
}

/** Expanded mode: a collapsible section whose sub-items sit on a vertical guide line. */
function NavParent({ item, depth }: { item: NavItem; depth: number }) {
  const { currentHref } = useNavListContext();
  const s = navListVariants({ collapsed: false });
  const IconCmp = item.icon;
  return (
    <Collapsible.Root defaultOpen={item.defaultOpen ?? navItemContainsCurrent(item, currentHref)}>
      <Collapsible.Trigger className={cn('group', depth === 0 ? cn(s.item(), s.parent()) : s.subItem(), 'w-full')}>
        {IconCmp && <IconCmp size={ICON_SIZE[depth === 0 ? 0 : 1]} aria-hidden className={cn(s.icon(), 'text-muted-foreground')} />}
        <span className={s.label()}>{item.label}</span>
        <Badge item={item} current={false} />
        <ChevronDown size={14} aria-hidden className={s.parentChevron()} />
      </Collapsible.Trigger>
      <Collapsible.Panel className={s.panel()}>
        <ul className={s.subList()}>
          {(item.items ?? []).map((child) => (
            <NavListEntry key={navItemKey(child)} item={child} depth={depth + 1} />
          ))}
        </ul>
      </Collapsible.Panel>
    </Collapsible.Root>
  );
}

/** Rail mode: the parent's icon opens a flyout menu listing its sub-items. */
function NavRailFlyout({ item }: { item: NavItem }) {
  const RouterLink = useLinkComponent();
  const { currentHref, onNavigate } = useNavListContext();
  const active = navItemContainsCurrent(item, currentHref);
  const s = navListVariants({ collapsed: true });
  const m = menuVariants();
  const IconCmp = item.icon;
  return (
    <Menu>
      <MenuTrigger aria-label={item.label} className={cn(s.item(), active && 'bg-accent text-accent-foreground')}>
        {active && <span aria-hidden className={s.indicator()} />}
        {IconCmp && <IconCmp size={ICON_SIZE[0]} aria-hidden className={s.icon()} />}
      </MenuTrigger>
      <MenuContent side="inline-end" align="start" sideOffset={10}>
        <MenuGroup>
          <MenuGroupLabel>{item.label}</MenuGroupLabel>
          {(item.items ?? []).map((child) => {
            const current = isNavItemCurrent(child, currentHref);
            const ChildIcon = child.icon;
            return child.href !== undefined ? (
              <BaseMenu.LinkItem
                key={navItemKey(child)}
                href={child.href}
                closeOnClick
                aria-current={current ? 'page' : undefined}
                render={RouterLink ? createElement(RouterLink) : undefined}
                className={cn(m.item(), 'no-underline', current && 'font-semibold text-primary-text')}
                onClick={(event) => {
                  child.onClick?.(event);
                  onNavigate?.(child);
                }}
              >
                {ChildIcon && <ChildIcon size={15} aria-hidden className={m.itemIcon()} />}
                <span className={m.itemLabel()}>{child.label}</span>
              </BaseMenu.LinkItem>
            ) : (
              <MenuItem
                key={navItemKey(child)}
                icon={ChildIcon}
                disabled={child.disabled}
                onClick={(event) => {
                  child.onClick?.(event);
                  onNavigate?.(child);
                }}
              >
                {child.label}
              </MenuItem>
            );
          })}
        </MenuGroup>
      </MenuContent>
    </Menu>
  );
}

/** One `<li>`: a leaf link/button, a collapsible parent, or (in the rail) a flyout parent. */
export function NavListEntry({ item, depth = 0 }: { item: NavItem; depth?: number }) {
  const { collapsed } = useNavListContext();
  let body: ReactNode;
  if (item.items?.length) body = collapsed && depth === 0 ? <NavRailFlyout item={item} /> : <NavParent item={item} depth={depth} />;
  else body = <NavLeaf item={item} depth={depth} />;
  return <li className="relative">{body}</li>;
}

export { NavList, type NavListProps } from './NavList';
export { isNavItemCurrent, type NavItem, type NavGroup, type NavIcon } from './nav-context';
export { navListVariants, type NavListVariantProps } from './nav-list.variants';
export { doc as navListDoc } from './NavList.doc';

import { createContext, useContext, type ComponentType, type MouseEvent, type ReactNode } from 'react';

export type NavIcon = ComponentType<{ size?: number; 'aria-hidden'?: boolean; className?: string }>;

export interface NavItem {
  /** Stable key; defaults to `href`, then `label`. */
  id?: string;
  label: string;
  /** Destination. Rendered through the LinkProvider's router link when one is set. Without it the item is a button. */
  href?: string;
  icon?: NavIcon;
  /** Count or short tag on the right (a dot in the collapsed rail). */
  badge?: ReactNode;
  /** Marks the item as the current page. Defaults to `href === currentHref`. */
  current?: boolean;
  disabled?: boolean;
  /** Nested sub-items: the item becomes a collapsible section (a flyout menu in the rail). */
  items?: NavItem[];
  /** Initial expansion of a nested section; defaults to open when it contains the current page. */
  defaultOpen?: boolean;
  onClick?: (event: MouseEvent<HTMLElement>) => void;
}

export interface NavGroup {
  id?: string;
  /** Group heading (mono, uppercase). Also names the group's list. */
  label?: string;
  items: NavItem[];
  /** Turns the heading into a toggle that folds the group. */
  collapsible?: boolean;
  defaultOpen?: boolean;
}

export interface NavContextValue {
  collapsed: boolean;
  currentHref?: string;
  onNavigate?: (item: NavItem) => void;
}

export const NavContext = createContext<NavContextValue>({ collapsed: false });
export const useNavListContext = () => useContext(NavContext);

export function isNavItemCurrent(item: NavItem, currentHref?: string): boolean {
  return item.current ?? (currentHref !== undefined && item.href !== undefined && item.href === currentHref);
}

export function navItemContainsCurrent(item: NavItem, currentHref?: string): boolean {
  return (item.items ?? []).some((child) => isNavItemCurrent(child, currentHref) || navItemContainsCurrent(child, currentHref));
}

export const navItemKey = (item: NavItem) => item.id ?? item.href ?? item.label;

import { tv, type VariantProps } from '../../utils/tv';

const focus = 'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring';

